const viewport=document.getElementById('viewport'),speed=document.getElementById('speed'),log=document.getElementById('log'),nameEl=document.getElementById('name'),descEl=document.getElementById('desc'),codeEl=document.getElementById('code'),meter=document.getElementById('meter'),status=document.getElementById('status'),rangeEl=document.getElementById('range'),sectorEl=document.getElementById('sector'),velocityEl=document.getElementById('velocity'),scanState=document.getElementById('scanState');
const catalog=[['SOL','Sol','G-type star / Solar System','starbody',96],['MERCURY','Mercury','Terrestrial planet / 0.39 AU','planet',24],['VENUS','Venus','Terrestrial planet / 0.72 AU','planet',32],['EARTH','Earth','Terrestrial planet / 1 AU','planet',88],['MARS','Mars','Terrestrial planet / 1.52 AU','planet',62],['JUPITER','Jupiter','Gas giant / 5.20 AU','gas',78],['SATURN','Saturn','Gas giant / 9.58 AU','gas',71],['URANUS','Uranus','Ice giant / 19.2 AU','ice',58],['NEPTUNE','Neptune','Ice giant / 30.1 AU','ice',66],['PLUTO','Pluto','Dwarf planet / Kuiper Belt','ice',44],['EUROPA','Europa','Jovian moon / subsurface ocean','ice',81],['TITAN','Titan','Saturnian moon / dense atmosphere','planet',76],['PROXIMA-B','Proxima Centauri b','Exoplanet / nearest stellar neighbour','planet',94],['TRAPPIST-1','TRAPPIST-1','Ultra-cool dwarf system / 12 pc','starbody',91],['KEPLER-186F','Kepler-186f','Earth-size exoplanet','planet',69],['BETELGEUSE','Betelgeuse','Red supergiant / Orion','starbody',83],['SIRIUS','Sirius','Binary star system / 8.6 ly','starbody',89],['ORION','Orion Nebula','Stellar nursery / M42','anomaly',97],['ANDROMEDA','Andromeda Galaxy','Spiral galaxy / M31','anomaly',99],['SAG-A','Sagittarius A*','Supermassive black hole / Galactic centre','anomaly',100],['UNKNOWN','ANOMALOUS CARRIER','Unresolved deep-space transmission','anomaly',100]];
let paused=false,boosted=false,spawnTimer=0,selected=null,distance=0;function addLog(t){log.innerHTML+='<br><span>['+new Date().toLocaleTimeString()+']</span> '+t;log.scrollTop=log.scrollHeight}function makeStars(){for(let i=0;i<115;i++){const s=document.createElement('i');s.className='star '+(i%5===0?'near':i%2?'far':'');s.style.left=Math.random()*100+'%';s.style.top=Math.random()*100+'%';s.style.setProperty('--len',(30+Math.random()*150)+'px');s.style.animationDuration=(1.2+Math.random()*2.4)+'s';s.style.animationDelay=(-Math.random()*3)+'s';viewport.appendChild(s)}}function makeSpeed(){for(let i=0;i<24;i++){const s=document.createElement('i');s.style.setProperty('--angle',(i*15)+'deg');s.style.setProperty('--len',(40+Math.random()*160)+'px');s.style.animationDelay=(-Math.random()*1)+'s';speed.appendChild(s)}}function spawn(){if(paused)return;const o=catalog[Math.floor(Math.random()*catalog.length)],el=document.createElement('div');el.className='body '+o[3];el.dataset.name=o[1];el.style.setProperty('--size',(10+Math.random()*45)+'px');el.style.setProperty('--x',(15+Math.random()*70)+'%');el.style.setProperty('--y',(15+Math.random()*70)+'%');el.style.setProperty('--glow',o[3]==='anomaly'?'#61f6c5':'rgba(150,190,190,.35)');el.style.setProperty('--duration',(5+Math.random()*6)/(boosted?1.8:1)+'s');el.title=o[1];el.addEventListener('click',()=>select(o,el));viewport.appendChild(el);setTimeout(()=>el.remove(),14000)}function select(o,el){document.querySelectorAll('.body').forEach(x=>x.classList.remove('selected'));el.classList.add('selected');selected=o;codeEl.textContent=o[0]+' // ACQUIRED';nameEl.textContent=o[1];descEl.textContent=o[2];meter.style.width=o[4]+'%';status.textContent=o[4]>90?'HIGH SIGNAL':o[4]>65?'ELEVATED':'NOMINAL';addLog('Object acquired: '+o[1]+' // signal '+o[4]+'%.')}function tick(){if(!paused){distance+=boosted?.7:.2;rangeEl.textContent=(distance+Math.random()*2).toFixed(1)+' ly';sectorEl.textContent=['ORION ARM','OUTER SYSTEM','LOCAL GROUP','DEEP FIELD','UNMAPPED'][Math.floor(distance/12)%5];if(Math.random()<.08)spawn();}requestAnimationFrame(tick)}makeStars();makeSpeed();for(let i=0;i<5;i++)spawn();setInterval(spawn,2500);tick();document.getElementById('pause').onclick=()=>{paused=!paused;document.getElementById('pause').textContent=paused?'[ RESUME FLIGHT ]':'[ PAUSE FLIGHT ]';scanState.textContent=paused?'PAUSED':'ACTIVE';status.textContent=paused?'HOLD':'CRUISING';addLog(paused?'Flight paused.':'Flight resumed.')};document.getElementById('boost').onclick=()=>{boosted=!boosted;velocityEl.textContent=boosted?'0.72c':'0.21c';document.getElementById('boost').textContent=boosted?'[ DISENGAGE BOOST ]':'[ ENGAGE BOOST ]';addLog(boosted?'FTL-assist drive engaged.':'Cruise velocity restored.')};document.getElementById('analyse').onclick=()=>{if(!selected){addLog('No object locked.');return}const results=['Atmospheric profile recorded.','Spectral signature acquired.','Mass estimate calculated.','Orbital parameters resolved.','Unexpected energy spike detected.'];addLog('Analysis '+selected[1]+': '+results[Math.floor(Math.random()*results.length)]);status.textContent='ANALYSING';setTimeout(()=>status.textContent='LOCKED',900)};document.getElementById('decode').onclick=()=>{if(!selected){addLog('No transmission target.');return}const phrases=['PATTERN 3 / 7 / 3','MULTI-BAND CARRIER','PARTIAL TRANSLATION','NON-RANDOM PULSE TRAIN','...SIGNAL REPEATS...'];addLog('Transmission decode: '+phrases[Math.floor(Math.random()*phrases.length)]);status.textContent='DECODING';setTimeout(()=>status.textContent='LOCKED',800)};document.getElementById('scramble').onclick=()=>{addLog('Signal scrambled. Sensor lock lost.');status.textContent='LOST';document.querySelectorAll('.body').forEach(x=>x.classList.remove('selected'));setTimeout(()=>status.textContent=paused?'HOLD':'CRUISING',1200)};document.getElementById('reset').onclick=()=>{viewport.querySelectorAll('.body').forEach(x=>x.remove());distance=0;selected=null;nameEl.textContent='No object acquired';descEl.textContent='Objects will enter the forward sensor field as the vessel travels. Click an object as it passes the ship to lock the scanner.';codeEl.textContent='DT-01 // DEEP SPACE';meter.style.width='63%';status.textContent='CRUISING';addLog('Navigation reset. Course recalculated.');for(let i=0;i<5;i++)spawn()};
